import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    columns = [
        "patch", "platform", "file_regexp", "required",
        "step", "description", "dir", "sha256",
    ]

    # The leading comments contain the schema, not a CSV header record.
    while True:
        position = stream.tell()
        line = stream.readline()
        if not line:
            break
        if not line.strip():
            continue
        comment = line.lstrip()
        if not comment.startswith("#"):
            stream.seek(position)
            break
        if re.match(r"#\s*Columns\s*:", comment, re.IGNORECASE):
            for group in re.findall(r"\(([^()]*)\)", comment):
                names = [name.strip() for name in group.split(";")]
                if len(names) > 1 and all(
                    re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name)
                    for name in names
                ):
                    columns = names
                    break

    reader = csv.reader(stream, delimiter=";", quotechar='"', doublequote=True)
    rows = []
    first = next(reader, None)
    if first is not None and first != columns:
        rows.append(first)
    rows.extend(reader)

    # Preserve extra fields and pad short records without discarding any rows.
    width = max(len(columns), max((len(row) for row in rows), default=0))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
